<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/health_network_v590.php';if(!hn590_bool('health_network_v590_public_pharmacies',true)){http_response_code(404);exit('Pharmacy directory unavailable.');}$id=(int)($_GET['id']??$_POST['pharmacy_id']??0);$p=hn590_pharmacy($id);if(!$p||$p['status']!=='active'||!$p['verified']){http_response_code(404);exit('Pharmacy not found.');}$flash='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$u=hn590_require_login('/pharmacy.php?id='.$id);$oid=hn590_create_pharmacy_order((int)$u['id'],$id,(int)($_POST['product_id']??0),(int)($_POST['qty']??1),!empty($_POST['prescription_id'])?(int)$_POST['prescription_id']:null,(string)($_POST['fulfillment']??'pickup'),trim((string)($_POST['delivery_address']??'')));$flash='Order request created successfully. Reference #'.$oid.'. Pharmacy staff will verify and confirm it.';}catch(Throwable $e){$error=$e->getMessage();}}$q=trim((string)($_GET['q']??''));$products=hn590_pharmacy_products($id,$q);$u=current_user();$rx=$u?hn590_user_prescriptions((int)$u['id']):[];hn590_track('pharmacy_view','pharmacy',$id);hn590_public_header($p['name'],'Browse pharmacy products and submit prescription-aware order requests.');
?><main><section class="hn590-provider-hero"><div class="hn590-shell"><a href="/pharmacies.php">← Pharmacies</a><div class="hn590-provider-title"><div class="hn590-bigicon">▣</div><div><span class="hn590-badge">VERIFIED PHARMACY</span><h1><?=e($p['name'])?></h1><p>⌖ <?=e($p['address']?:$p['area'])?> · <?=e($p['phone']?:'Portal contact')?></p></div></div><div class="hn590-pills"><span><?=$p['delivery_available']?'✓ Delivery':'Delivery unavailable'?></span><span><?=$p['pickup_available']?'✓ Pickup':'Pickup unavailable'?></span></div></div></section><section class="hn590-section"><div class="hn590-shell"><?php if($flash):?><div class="hn590-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="hn590-alert err"><?=e($error)?></div><?php endif;?><form class="hn590-search"><input name="id" type="hidden" value="<?=$id?>"><input name="q" value="<?=e($q)?>" placeholder="Search medicine/product name or category"><button class="hn590-btn primary">Search</button></form><div class="hn590-product-grid"><?php if(!$products):?><div class="hn590-empty">No published products found.</div><?php endif;?><?php foreach($products as $x):?><article><div class="hn590-med-icon">+</div><small><?=e($x['category']?:'Pharmacy Item')?></small><h3><?=e($x['name'])?></h3><?php if($x['generic_name']):?><p><?=e($x['generic_name'])?><?=($x['strength']?' · '.e($x['strength']):'')?></p><?php endif;?><strong><?=hn590_money((float)$x['price'])?></strong><div class="hn590-stock <?=$x['stock_qty']>0?'in':'out'?>"><?=$x['stock_qty']>0?e((string)$x['stock_qty']).' in stock':'Out of stock'?></div><?php if($x['prescription_required']):?><span class="hn590-rx">Prescription required</span><?php endif;?><?php if((int)$x['stock_qty']>0):?><details><summary>Order / Request</summary><form method="post" class="hn590-order-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="pharmacy_id" value="<?=$id?>"><input type="hidden" name="product_id" value="<?=(int)$x['id']?>"><label>Quantity<input type="number" name="qty" value="1" min="1" max="25"></label><?php if($x['prescription_required']):?><label>Prescription<select name="prescription_id" required><option value="">Select your prescription</option><?php foreach($rx as $r):?><option value="<?=(int)$r['id']?>"><?=e($r['prescription_no'].' · '.$r['doctor_name'])?></option><?php endforeach;?></select></label><?php endif;?><label>Fulfillment<select name="fulfillment"><option value="pickup" <?=$p['pickup_available']?'':'disabled'?>>Pickup</option><option value="delivery" <?=$p['delivery_available']?'':'disabled'?>>Delivery</option></select></label><label>Delivery address (if delivery)<textarea name="delivery_address"></textarea></label><button class="hn590-btn primary">Submit Order Request</button></form></details><?php endif;?></article><?php endforeach;?></div><div class="hn590-safety-card"><b>Medication safety</b><p>Catalog availability is informational. Prescription-required products require a valid prescription and pharmacy verification. The portal does not provide dosing instructions or replace advice from a qualified clinician/pharmacist.</p></div></div></section></main><?php hn590_public_footer();?>
